# generated by tools/ail2py.py from csv_column_stats_main.ail; edit the .ail until onelang s16
from csv_column_stats import *
from file_identity import *
from ail import read_bytes, write_bytes
import sys

def main() -> int:
    if len(sys.argv) != 4:
        print('usage: csv_column_stats INPUT OUTPUT ZERO_BASED_COLUMN', file=sys.stderr)
        return 2
    try:
        input: str = sys.argv[1]
        output: str = sys.argv[2]
        column: int = parse_int64_decimal(sys.argv[3])
        if column < 0 or input == output or file_paths_same(input, output):
            raise ValueError
        stats: IntegerColumnStats = csv_column_stats(read_bytes(input).decode(), column)
        write_bytes(output, integer_column_stats_render(stats).encode())
        return 0
    except (ValueError, IndexError, UnicodeDecodeError, OSError):
        print('invalid CSV, integer, column, path or file operation', file=sys.stderr)
        return 2
    return 0

if __name__ == "__main__":
    sys.exit(main())
